// Terminal render/theme constants shared by the xterm PTY mount (TerminalView).
// Pure module-level values — no xterm/PTY/React coupling — extracted so the mount
// module stays focused on the effect wiring.

// The bounded hold for output that is NOT in the recording — the only case disk cannot answer, which
// in practice is a handful of emitter-generated notices. It fills up only when a session's recording
// failed to open, and then it is that session's sole copy, so it stays bounded.
//
// SMALLER THAN THE 256 KB IT REPLACES, deliberately. The old cap sized a buffer holding EVERY hidden
// pane's output; this one holds only what the recording does not, so a large value would budget for a
// case that should be rare and would make the truncation notice arrive later than it is useful. See
// `@/app/console/lib/terminalHandoff` for why an overflow resets rather than shifts.
export const UNRECORDED_BYTES_CAP = 32 * 1024;

// How much recorded scrollback a reveal replays when a pane becomes visible again.
//
// A PREFERENCE THE READER MAY OVERSHOOT, not a limit it may violate: the replay always begins at a
// SAFE BOUNDARY. `scrollback::replay_start` takes the smallest recorded mark that fits this budget and
// returns the last mark ANYWAY when even that does not, because starting mid-sequence is the exact
// corruption the whole mechanism exists to prevent. 512 KB is roughly 6k lines of dense output — more
// history than the buffer this replaces could hold even before it began dropping the front off it.
export const REVEAL_MAX_BYTES = 512 * 1024;

// Grace before the automatic post-launch redraw nudge (#1221) — long enough for Claude's TUI to
// finish its first paint, so the nudge repaints a fully-drawn (and possibly jumbled) screen rather
// than an empty one. The nudge is idempotent + non-destructive, so an imprecise delay is harmless.
export const AUTO_NUDGE_DELAY_MS = 700;

// Mid-session jumble probe (#1250): at each Claude settle, sample the bottom input-box rows and
// auto-nudge when the box chrome is shattered. Hysteresis — two malformed samples (the settle + one
// quick re-check) before firing — so a lone mid-draw frame doesn't trigger a needless repaint.
// (#1239 reverted the input overlay/clip box, so these now guard Claude's own native input box.)
export const JUMBLE_CHROME_ROWS = 10; // bottom viewport rows that hold Claude's input box + hint lines
export const JUMBLE_STRIKES = 2;
export const JUMBLE_RECHECK_MS = 250;

